<?php
 namespace QQWorld\Downloadable\Controller\Download; use QQWorld\Downloadable\Helper\Download as DownloadHelper; use QQWorld\Framework\App\ResponseInterface; class LinkSample extends \QQWorld\Downloadable\Controller\Download { public function execute() { $linkId = $this->getRequest()->getParam('link_id', 0); $link = $this->_objectManager->create(\QQWorld\Downloadable\Model\Link::class)->load($linkId); if ($link->getId()) { $resource = ''; $resourceType = ''; if ($link->getSampleType() == DownloadHelper::LINK_TYPE_URL) { $resource = $link->getSampleUrl(); $resourceType = DownloadHelper::LINK_TYPE_URL; } elseif ($link->getSampleType() == DownloadHelper::LINK_TYPE_FILE) { $resource = $this->_objectManager->get( \QQWorld\Downloadable\Helper\File::class )->getFilePath( $this->_getLink()->getBaseSamplePath(), $link->getSampleFile() ); $resourceType = DownloadHelper::LINK_TYPE_FILE; } try { $this->_processDownload($resource, $resourceType); exit(0); } catch (\Exception $e) { $this->messageManager->addError( __('Sorry, there was an error getting requested content. Please contact the store owner.') ); } } return $this->getResponse()->setRedirect($this->_redirect->getRedirectUrl()); } } 